routes.body:
let environment = dispatch_support::optional_string(request, "environment");
let sdk_config = dispatch_support::optional_value::<flare_im_core_sdk::client::lifecycle::SdkConfigOverlay>(request, "sdkConfig")?;
session.client().init(environment, sdk_config).await?;

let request = dispatch_support::from_value::<flare_im_core_sdk::model::SyncConversationSummariesRequest>(
    request.clone(),
    "sync conversation summaries request",
)?;
let response = client.sync_conversation_summaries_with_versions(request).await?;

let request = dispatch_support::from_value::<flare_im_core_sdk::model::StartupHomeSyncRequest>(
    request.clone(),
    "startup home sync request",
)?;
let response = client.bootstrap_startup_home(request).await?;

let conversation_id = dispatch_support::json_string(request, "conversationId")?;
let limit = dispatch_support::optional_i32(request, "limit")?.unwrap_or(500);
let max_pages = dispatch_support::optional_u32(request, "maxPages")?.unwrap_or(128);
let response = client.backfill_conversation_history(&conversation_id, limit, max_pages).await?;

let conversation_id = dispatch_support::json_string(request, "conversationId")?;
let last_seq = dispatch_support::json_u64(request, "lastSeq")?;
let limit = dispatch_support::optional_i32(request, "limit")?.unwrap_or(50);
client.sync_messages(&conversation_id, last_seq, limit).await?;

let secret = dispatch_support::json_string(request, "secret")?;
let issuer = dispatch_support::json_string(request, "issuer")?;
let user_id = dispatch_support::json_string(request, "userId")?;
let ttl_secs = dispatch_support::json_u64(request, "ttlSecs")?;
let device_id = dispatch_support::optional_string(request, "deviceId");
let tenant_id = dispatch_support::optional_string(request, "tenantId");
let token = flare_im_core_sdk::client::IMClient::generate_core_token(
    flare_im_core_sdk::client::CoreTokenConfig {
        secret,
        issuer,
        user_id,
        ttl_secs,
        device_id,
        tenant_id,
    },
)?;

let access_token = dispatch_support::json_string(request, "accessToken")?;
let tenant_id = dispatch_support::optional_string(request, "tenantId");
client
    .update_access_token(access_token, tenant_id.as_deref())
    .await?;

let nat_timeout_secs = dispatch_support::optional_u32(request, "natTimeoutSecs")?;
client
    .set_heartbeat_nat_timeout(nat_timeout_secs.map(|secs| std::time::Duration::from_secs(secs as u64)))
    .await?;

let interval = client.heartbeat_effective_interval().await?;
let response = match interval {
    Some(duration) => serde_json::json!({
        "connected": true,
        "intervalMs": duration.as_millis() as u64,
        "intervalSecs": duration.as_secs(),
    }),
    None => serde_json::json!({
        "connected": false,
        "intervalMs": null,
        "intervalSecs": null,
    }),
};

let event = flare_im_core_sdk::client::NetworkChangeEvent {
    available: dispatch_support::optional_bool(request, "available")?.unwrap_or(true),
    interface: dispatch_support::optional_string(request, "interface"),
    expensive: dispatch_support::optional_bool(request, "expensive")?,
    metered: dispatch_support::optional_bool(request, "metered")?,
    reason: dispatch_support::optional_string(request, "reason"),
};
let reconnected = client.notify_network_change(event).await?;

let conversation_id = dispatch_support::json_string(request, "conversationId")?;
let text = dispatch_support::json_string(request, "text")?;
let mention_users = dispatch_support::optional_value::<Vec<String>>(request, "mentionUsers")?.unwrap_or_default();
let mention_all = dispatch_support::optional_bool(request, "mentionAll")?.unwrap_or(false);
let api = session.message_build_api().await?;
let message = api.create_text(&conversation_id, &text, mention_all, &mention_users).await?;

let markdown = dispatch_support::json_string(request, "markdown")?;
let normalized = dispatch_support::run_cpu_bound(
    "rich_doc_v2.normalize_from_markdown",
    move || {
        flare_im_core_sdk::content::rich_doc_v2::normalize_from_markdown(&markdown)
            .map_err(|error| crate::binding_invalid_parameter(error.to_string()))
    },
)
.await?;
let source_payload = normalized
    .source_payload
    .as_ref()
    .map(|(key, value)| serde_json::json!({ key: value }));

let html = dispatch_support::json_string(request, "html")?;
let normalized = dispatch_support::run_cpu_bound(
    "rich_doc_v2.normalize_from_html",
    move || {
        flare_im_core_sdk::content::rich_doc_v2::normalize_from_html(&html)
            .map_err(|error| crate::binding_invalid_parameter(error.to_string()))
    },
)
.await?;
let source_payload = normalized
    .source_payload
    .as_ref()
    .map(|(key, value)| serde_json::json!({ key: value }));

let doc_json = dispatch_support::json_string(request, "docJson")?;
let normalized = dispatch_support::run_cpu_bound(
    "rich_doc_v2.normalize_from_doc_json",
    move || {
        flare_im_core_sdk::content::rich_doc_v2::normalize_from_doc_json(&doc_json)
            .map_err(|error| crate::binding_invalid_parameter(error.to_string()))
    },
)
.await?;
let source_payload = normalized
    .source_payload
    .as_ref()
    .map(|(key, value)| serde_json::json!({ key: value }));

let snapshot = client.runtime_health_snapshot().await;
let metrics_json = serde_json::to_string(&snapshot.metrics).unwrap_or_else(|_| "{}".to_string());
let (state, state_code) = sdk_state_json(snapshot.state);

let api = session.media_api().await?;
let download_key = dispatch_support::json_string(request, "downloadKey")?;
let cancelled = api.cancel_user_file_download(&download_key);

let api = session.media_api().await?;
let download_key = dispatch_support::json_string(request, "downloadKey")?;
let display_file_name = dispatch_support::json_string(request, "displayFileName")?;
let source_path = dispatch_support::optional_string(request, "sourcePath");
let source_http_url = dispatch_support::optional_string(request, "sourceHttpUrl");
let remote_file_id = dispatch_support::optional_string(request, "remoteFileId");
let expires_in = dispatch_support::optional_i32(request, "expiresIn")?.unwrap_or(3600);
let path = api.download_file_to_user_downloads_folder(flare_im_core_sdk::prelude::UserFileDownloadRequest {
    download_key,
    display_file_name,
    source_path,
    source_http_url,
    remote_file_id,
    expires_in,
    on_progress: None,
}).await?;
